from pathlib import Path
import json,statistics,math
R=Path('/private/tmp/light-models');d=json.loads((R/'evidence/metrics.json').read_text())
cs=json.loads((R/'evidence/per-call-input.json').read_text());fs=json.loads((R/'evidence/first-request.json').read_text())
mean=statistics.mean
p90=lambda a:sorted(a)[math.ceil(.9*len(a))-1]
t=['','## First-repeat input and cache measurements','','Input includes cached tokens. Cache share is summed cached input / summed input, weighted across calls. First-request sizes are means across the 12 tasks for each arm. JSON bytes are compact UTF-8 serialization of the captured forwarded body, not HTTP framing bytes. System/schema lengths are characters. Per-call usage and every first request are in [per-call-input.csv](evidence/per-call-input.csv) and [first-request.csv](evidence/first-request.csv); missing usage is flagged explicitly.','', '| Model | Agent | Calls | Input/call mean | Input/call median / p90 | Cached input share | First input tokens | First system / schema chars | First JSON bytes |','|---|---|---:|---:|---:|---:|---:|---:|---:|']
for m in ['grok-4.7','gpt-6-sol','MiniMax-M3']:
 for a in ['pi','light-main','light-port']:
  c=[x for x in cs if x['model']==m and x['agent']==a];f=[x for x in fs if x['model']==m and x['agent']==a]
  if not c:continue
  ins=[x['input_tokens'] for x in c]
  t.append(f"| {m} | {a} | {len(c)} | {mean(ins):,.1f} | {statistics.median(ins):,.1f} / {p90(ins):,} | {sum(x['cached_tokens'] for x in c)/sum(ins):.2%} | {mean(x['input_tokens'] for x in f):,.1f} | {mean(x['system_chars'] for x in f):,.0f} / {mean(x['schema_chars'] for x in f):,.0f} | {mean(x['body_json_utf8_bytes'] for x in f):,.0f} |")
t+=['','## Round closure and reserved capacity','','The owner limited this round to repeat one for all three agents and models. No second repeat is authorized or launched. The queued MiniMax repeat-two coordinator was stopped explicitly (Mac PID 48024). The remaining allowances are reserved for a later coordinator-supplied converged revision; existing ledgers must carry forward.','', '| Provider | Used | Remaining allowance |','|---|---:|---:|']
for p,cap in [('grok',800),('openai',600),('minimax',6)]:
 v=d['ledgers'][p];money=p=='minimax';n=v['charged_usd'] if money else v['admitted'];t.append(f'| {p} | '+(f'${n:.6f}' if money else str(n))+' | '+(f'${cap-n:.6f}' if money else str(cap-n))+' |')
t+=['','Sol totals include its one availability request (346 benchmark calls plus one preflight). No Sol task overlaps main Luna calls. Both Light arms fit this first repeat; port 3c954 led the full DeepSeek completion results at launch, but no arm had to be dropped.','', 'Setup failures retained: initial Grok bridge startup failed because its native helper/dependency was absent from the copied task tree; repairing those private copies restored normal in-process OAuth refresh and live model discovery, with no generation requests lost. Both Grok task12 raw trace failures are separately listed above as evidence-format failures. Provider-call errors and missing usage are included in the accounting and failure records; completed artifact failures and deadline/call-limit failures are never discarded.','', 'Reproduction and future-run instructions: [harness/README.md](harness/README.md). Retain the current agent copies, frozen task repositories, all runner versions, bridges, derived audit traces, admissions and spend ledgers. A later revision needs a distinct run namespace and explicit coordinator resumption; never overwrite or reuse these cell IDs.']
t+=['', 'The task04 Pi trace contains 23 bash, 19 read and 2 edit calls before its last admitted request; the artifact lacks a typed stub. Task04 port contains 23 exec_command and 21 FileRead calls, still inspecting source before reaching the cap; its artifact lacks count_by. Task07 main remains in inspection and continuation requests at its deadline; the executable script is absent. These observations describe the retained traces, without attributing the differences to prompt wording.', '', 'A preliminary credential scan and offline audit overlapped MiniMax work around 19:09–19:10 UTC. This own-job disk activity is an additional timing caveat alongside the measured other-job overlap; no wall times are adjusted. One repeat gives descriptive comparisons, not a stable model ranking.']
for name,title in [('final-audit.json','Final audit'),('shutdown.json','Owned process shutdown'),('scan-summary.json','Credential scan')]:
 p=R/'evidence'/name
 if p.exists():t+=['',title+': `'+json.dumps(json.loads(p.read_text()),separators=(',',':'))+'`.']
p=R/'REPORT.md';p.write_text(p.read_text()+'\n'.join(t)+'\n')
